interface.signature:
interface NumbersSession {
  id: string;
  userId: string;
  formatType: 'dates' | 'phoneNumbers' | 'calculations' | 'measurements' | 'mixed';
  difficulty: 'beginner' | 'intermediate' | 'advanced';
  content: string;
  numberCount: number;
  specialChars: string[];
  createdAt: Timestamp;
  numberPadAccuracy: number;
  mainKeyboardAccuracy: number;
}

interface UserNumbersProgress {
  userId: string;
  formatProficiency: {
    [formatType: string]: {
      totalSessions: number;
      averageWpm: number;
      averageAccuracy: number;
      numberPadAccuracy: number;
      bestWpm: number;
      bestAccuracy: number;
    };
  };
}

interface NumbersModeProps extends TypingAreaProps {
  formatType: string;
  numberPadOptimization: boolean;
  numbersMode: true;
  onFormatChange: (format: string) => void;
  mixedContentSupport: boolean;
}
